/// A riscv-opcodes extension: the file that defines an instruction, such as `rv_i`, `rv64_i`, or `rv_m`. The RV64
/// additions to an extension are their own, so RV64I is `rv_i` and `rv64_i` together.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Ext {
    Rv32C,
    Rv32CF,
    Rv64A,
    Rv64C,
    Rv64D,
    Rv64F,
    Rv64I,
    Rv64M,
    RvA,
    RvC,
    RvCD,
    RvD,
    RvF,
    RvI,
    RvM,
    RvS,
    RvSystem,
    RvV,
    RvZicsr,
    RvZifencei,
    RvZvbb,
}

impl Ext {
    /// Every extension that defines an instruction, in name order.
    pub const ALL: &'static [Ext] = &[
        Ext::Rv32C,
        Ext::Rv32CF,
        Ext::Rv64A,
        Ext::Rv64C,
        Ext::Rv64D,
        Ext::Rv64F,
        Ext::Rv64I,
        Ext::Rv64M,
        Ext::RvA,
        Ext::RvC,
        Ext::RvCD,
        Ext::RvD,
        Ext::RvF,
        Ext::RvI,
        Ext::RvM,
        Ext::RvS,
        Ext::RvSystem,
        Ext::RvV,
        Ext::RvZicsr,
        Ext::RvZifencei,
        Ext::RvZvbb,
    ];

    /// The extension's riscv-opcodes name, such as `rv64_i`.
    pub const fn name(self) -> &'static str {
        match self {
            Ext::Rv32C => "rv32_c",
            Ext::Rv32CF => "rv32_c_f",
            Ext::Rv64A => "rv64_a",
            Ext::Rv64C => "rv64_c",
            Ext::Rv64D => "rv64_d",
            Ext::Rv64F => "rv64_f",
            Ext::Rv64I => "rv64_i",
            Ext::Rv64M => "rv64_m",
            Ext::RvA => "rv_a",
            Ext::RvC => "rv_c",
            Ext::RvCD => "rv_c_d",
            Ext::RvD => "rv_d",
            Ext::RvF => "rv_f",
            Ext::RvI => "rv_i",
            Ext::RvM => "rv_m",
            Ext::RvS => "rv_s",
            Ext::RvSystem => "rv_system",
            Ext::RvV => "rv_v",
            Ext::RvZicsr => "rv_zicsr",
            Ext::RvZifencei => "rv_zifencei",
            Ext::RvZvbb => "rv_zvbb",
        }
    }
}
